INSERT INTO "posts" ("title", "image_url", "content", "slug", "published", "created_at", "updated_at") VALUES
('Circuito Despertar 2023 - Etapa da Torre dia 13 de maio', 'https://9nkvm1j67x.ufs.sh/f/sYfAN6LQ1AETAigvVYzF4b1RokWMtEncvNGripeqTUfhYIO2', 'A Etapa da Torre do Circuito Despertar 2023 será realizada dia 13 de maio às 13h no Instituto Federal de Sergipe - Campus Socorro localizado na Av. Perimetral B, nº 94, Conjunto Marcos Freire II em Nossa Senhora do Socorro.
INSERT INTO "announcements" ("id", "year", "number", "content") VALUES
(1, 2023, 1, 'José Gustavo dos Santos Marques recebe o título de Grande Mestre Sergipano, tendo cumprido todos os requisitos. Em breve receberá o diploma e fará parte da lista de titulados.'),
